The reference formulation has three complementary components.
\begin{enumerate}
\item For the equilateral octahedral seam with Kirchhoff conditions, its $\Pi_3$-invariant Laplacian is a Neumann interval operator. A normalized heat trace is the Jacobi theta function, and its Mellin transform is $\pi^{-s/2}\Gamma(s/2)\zeta(s)$; see Theorems~\ref{thm:interval} and~\ref{thm:seamzeta}.
\item For the specified sheetwise energy form, a unique nonnegative self-adjoint operator governs propagation. Its weak gluing law is continuity of trace together with conservation of conormal flux; see Theorem~\ref{thm:sheetoperator}. Cusp collars and global automorphic states have the Fourier--Bessel and Mellin descriptions of Theorems~\ref{thm:cusp} and~\ref{thm:maassFE}.
\item An enriched tower whose state transitions commute with Mellin transformation and whose duality respects those transitions has an assembled completed state satisfying the induced reflection law; see Theorem~\ref{thm:assembly}. The rank-two residue calculation in Theorem~\ref{thm:ranktwo} gives an explicit model of such a transition.
\end{enumerate}

For each $p\in\mathcal P$, let $\mathcal A_p$ index a family of open leaves $L_{p,a}\cong(0,1)\times S^1$, with their two ends labeled by the two vertices in $p$. An incidence relation on their end compactifications defines
\begin{equation}\label{eq:FS}
\mathrm{FS}(X)=\left(\bigsqcup_{p\in\mathcal P}\ \bigsqcup_{a\in\mathcal A_p}
\widehat L_{p,a}\right)\Big/\!\sim_{\mathrm{inc}}.
\end{equation}
A realization includes the topology, the incidence maps, and a $\Pi_3$ action preserving this structure. Its regular regions may be foliated; its shared strata are recorded explicitly by $\sim_{\mathrm{inc}}$.

\label{prop:cross}
The graph $C_{\partial X}$ is a subdivision of the octahedral graph $K_{2,2,2}$. It has six degree-four vertices, twelve degree-two vertices, and twenty-four subdivided edges. Suppressing the degree-two vertices gives a graph with six vertices and twelve edges, and
\begin{equation}
\overline C_{\partial X}\cong\Gamma_3:=K_{2,2,2},
\qquad b_1(\Gamma_3)=7.
\end{equation}
These identifications are equivariant for the cube's full symmetry group $\Pi_3\cong B_3\cong O_h$.

\label{def:seed}
A three-seed is a datum $\mathfrak S_3=(\mathcal I_3,\Gamma_3,\Pi_3)$ with
\begin{equation}
\mathcal I_3=\left(\bigsqcup_{p\in\mathcal P}X_p\right)\Big/\!\sim_{\Gamma_3},
\qquad \Gamma_3\cong K_{2,2,2},
\qquad \Pi_3\cong O_h.
\end{equation}
The datum includes the marked seam strata on the sheets, their attaching maps, and an action preserving the resulting incidence structure. Each sheet has two distinguished ends, labeled by the pair $p$. Conical compactifications and cusp metrics are analytic enrichments specified below.

\label{lem:graphform}
The form $q_\Gamma$ on $V_\Gamma$ is densely defined, nonnegative, and closed. Its associated operator $A_\Gamma$ acts as $-d^2/dx^2$ on each edge, with domain consisting of edgewise $H^2$ functions satisfying continuity and
\begin{equation}\label{eq:Kirchhoff}
\sum_{e\ni v}\partial_e f(v)=0
\end{equation}
at every vertex. Here $\partial_e$ points from the vertex into the edge. The operator has compact resolvent.

\label{thm:interval}
The operator $A_\Gamma^{\Pi_3}$ is unitarily equivalent to the Neumann Laplacian on $[0,\ell/2]$. Its eigenvalues are simple and equal to
\begin{equation}\label{eq:invariantspectrum}
\lambda_m=\left(\frac{2\pi m}{\ell}\right)^2,
\qquad m=0,1,2,\ldots.
\end{equation}
On every edge, the corresponding invariant eigenfunction is proportional to $\cos(2\pi mx/\ell)$.

\label{cor:seamheat}
Set $\mathsf H_\Gamma=\ell^2A_\Gamma^{\Pi_3}/(4\pi)$ and define
\begin{equation}\label{eq:seamtheta}
Z_\Gamma(t)=\operatorname{Tr}(e^{-t\mathsf H_\Gamma}),
\qquad \theta_\Gamma(t)=2Z_\Gamma(t)-1.
\end{equation}
Then, for $t>0$,
\begin{equation}
Z_\Gamma(t)=\sum_{m=0}^\infty e^{-\pi m^2t},
\qquad
\theta_\Gamma(t)=\sum_{m\in\mathbb Z}e^{-\pi m^2t}.
\end{equation}

A length scale contributes a Mellin factor only after the operator and spectral variable are fixed. For the positive spectrum above,
\begin{equation}
\operatorname{Tr}{}'\bigl((A_\Gamma^{\Pi_3})^{-z}\bigr)
=\left(\frac{\ell}{2\pi}\right)^{2z}\zeta(2z),\qquad \Re z>\tfrac12.
\end{equation}
The triangular length $3\ell$ and the seam period $\ell$ are both geometrically meaningful; Proposition~\ref{prop:triangleharmonics} explains their relation before any factor such as $3^{-s}$ is introduced.

\label{lem:poisson}
For the Fourier convention $\widehat f(\xi)=\int_\mathbb R f(x)e^{-2\pi ix\xi}\,d x$,
\begin{equation}
\widehat{e^{-\pi t x^2}}(\xi)=t^{-1/2}e^{-\pi\xi^2/t},\qquad t>0.
\end{equation}
For a Schwartz function $f$,
$\sum_{m\in\mathbb Z}f(m)=\sum_{m\in\mathbb Z}\widehat f(m)$.

\label{thm:thetareciprocity}
The state in~\eqref{eq:seamtheta} satisfies
\begin{equation}\label{eq:thetareciprocity}
\theta_\Gamma(t)=t^{-1/2}\theta_\Gamma(1/t).
\end{equation}

\label{thm:seamzeta}
For $\Re s>1$, the Mellin state
\begin{equation}\label{eq:seamMellin}
\Lambda_{\zeta}(s):=\int_0^\infty\bigl(Z_\Gamma(t)-1\bigr)t^{s/2}\frac{\,d t}{t}
\end{equation}
is equal to $\pi^{-s/2}\Gamma(s/2)\zeta(s)$. It has a meromorphic continuation to $\mathbb C$ with simple poles at $0,1$, of residues $-1,1$, and satisfies
\begin{equation}\label{eq:zetaFE}
\Lambda_{\zeta}(s)=\Lambda_{\zeta}(1-s).
\end{equation}
The function $\xi(s)=\tfrac12s(s-1)\Lambda_{\zeta}(s)$ is entire and obeys $\xi(s)=\xi(1-s)$.

For real $s>1$, Tonelli's theorem gives
\begin{align}
\int_0^\infty\sum_{m\ge1}e^{-\pi m^2t}t^{s/2}\frac{\,d t}{t}
&=\sum_{m\ge1}(\pi m^2)^{-s/2}\Gamma(s/2)\\
&=\pi^{-s/2}\Gamma(s/2)\zeta(s).
\end{align}
The same calculation bounds the absolute value for complex $s$ by the expression at $\Re s$, proving absolute convergence and the identity on $\Re s>1$.

Using $Z_\Gamma-1=(\theta_\Gamma-1)/2$, split the integral at $1$. On $(0,1)$ insert~\eqref{eq:thetareciprocity} and substitute $t\mapsto1/t$ in the decaying part. This yields
\begin{equation}\label{eq:splitMellin}
\Lambda_{\zeta}(s)=\frac1{s-1}-\frac1s+
\frac12\int_1^\infty(\theta_\Gamma(t)-1)
\left(t^{s/2}+t^{(1-s)/2}\right)\frac{\,d t}{t}.
\end{equation}
The integral is entire: on every compact $s$-set its integrand and all $s$-derivatives are bounded by a polynomial in $t$ and $\log t$ times $Ce^{-\pi t}$. The rational part supplies exactly the stated poles and residues. Both parts of~\eqref{eq:splitMellin} are invariant under $s\mapsto1-s$. Multiplication by $s(s-1)/2$ cancels the two poles and preserves the reflection.

\label{prop:actionangle}
Let $a,b,T>0$, let $u\in(0,a/b)$ and $v\in\mathbb R/T\mathbb Z$, and set
\begin{equation}\label{eq:actionangle}
g_\phi=\frac{du^2}{\phi(u)}+\phi(u)\,dv^2,
\qquad \phi(u)=au-bu^2.
\end{equation}
The metric has area form $du\,dv$, Gaussian curvature $b$, and scalar curvature $2b$. Its metric completion has two conical points, each of angle $aT/2$, and total area $aT/b$.

\label{def:analyticseed}
An admissible scalar enrichment of the three-seed consists of:
\begin{enumerate}
\item a finite collection of smooth Riemannian surface pieces $M_\alpha$, obtained by cutting the sheets along the seam, with piecewise smooth compact seam boundaries and the prescribed cusp ends;
\item arclength identifications of incident seam edges, with positive constant weights $\kappa_\alpha$;
\item a $\Pi_3$ action carrying the pieces, metrics, weights, and attaching maps to one another;
\item chosen external boundary conditions, if external boundary is present.
\end{enumerate}
The Sobolev spaces are defined using the intrinsic metrics. The seam traces satisfy the usual bounded trace maps into the trace spaces of the compact boundary arcs. At boundary corners, these are understood as the traces of global $H^1$ functions on each piece.

\label{thm:sheetoperator}
The form $q_3$ is densely defined, nonnegative, and closed. It determines a unique nonnegative self-adjoint operator $A_3$. On smooth portions of its domain, $A_3u=-\Delta u$ on each piece, and along every open seam edge $e$ its matching conditions are
\begin{equation}\label{eq:sheetmatching}
u_\alpha|_e=h_e\quad(\alpha\in I(e)),\qquad
\sum_{\alpha\in I(e)}\kappa_\alpha\partial_{\nu_\alpha}u_\alpha|_e=0.
\end{equation}
Here $\nu_\alpha$ is the outward conormal of the cut piece. The operator and its functional calculus commute with $\Pi_3$.

\label{thm:harmonic}
For every admissible external trace $b\in\operatorname{Tr}_{\mathrm{ext}}V(K)$, there is a unique energy-minimizing $u_b\in V(K)$ with trace $b$. It is characterized by
\begin{equation}
q_K(u_b,v)=0\qquad(v\in V_0(K)).
\end{equation}
It is harmonic on the interiors, satisfies the conservative seam condition, and depends continuously on $b$ in the quotient trace norm. The extension map is equivariant whenever the boundary datum is.

\label{prop:defect}
Let $u\in V_3$ satisfy $(-\Delta-\lambda)u_\alpha=0$ on each piece, with conormal derivatives interpreted in the weak trace sense. Its failure to solve the global weak eigenvalue equation is the seam functional
\begin{equation}\label{eq:defect}
\mathfrak d_e(u)=\sum_{\alpha\in I(e)}\kappa_\alpha\partial_{\nu_\alpha}u_\alpha|_e.
\end{equation}
Specifically, for test functions supported away from external boundary,
\begin{equation}
q_3(u,v)-\lambda\langle u,v\rangle_{H_3}
=\sum_e\langle\mathfrak d_e(u),\operatorname{Tr}_ev\rangle.
\end{equation}
Thus $u$ is a global weak state precisely when all these seam functionals vanish.

\label{prop:DtN}
Cut a compact core into finitely many pieces and fix homogeneous external boundary conditions. Let $\lambda$ lie outside the Dirichlet spectra of the cut pieces. For an admissible seam trace $h$, solve the piecewise eigenvalue equations and let $\mathcal D_\Gamma(\lambda)h$ be the weighted sum of their conormal derivatives. Then the trace map identifies global eigenfunctions at $\lambda$ with
\begin{equation}
\ker\mathcal D_\Gamma(\lambda).
\end{equation}
For real $\lambda$ in this domain, $\mathcal D_\Gamma(\lambda)$ is symmetric under the trace duality pairing.

\label{lem:reciprocallog}
For $a,\sigma>0$,
\begin{equation}
\int_0^\infty e^{-\sigma/t-at}\,d t
=2\sqrt{\frac{\sigma}{a}}K_1(2\sqrt{a\sigma}).
\end{equation}
More generally, for $\nu\in\mathbb C$,
\begin{equation}\label{eq:Besselintegral}
\int_0^\infty t^{\nu-1}e^{-at-\sigma/t}\,d t
=2(\sigma/a)^{\nu/2}K_\nu(2\sqrt{a\sigma}).
\end{equation}

A transfer to the eight cusp collars is a linear map
\begin{equation}
\mathcal R:\mathcal B_{\partial X}\longrightarrow\bigoplus_{v\in V}C^\infty(S^1),
\end{equation}
where $\mathcal B_{\partial X}$ is a specified space of decorated panel fields. A concrete choice integrates corner fields against smooth kernels on the face variables and the output circle. Mean-zero projection $Q_0b=b-\int_0^1b(x)\,d x$ selects the nonconstant channel.

\label{prop:transfer}
For representations $U^{\mathrm{in}}$ and $U^{\mathrm{out}}$ of ${\Pi_3}$, the average
\begin{equation}
\mathcal R_{{\Pi_3}}=\frac1{48}\sum_{g\in{\Pi_3}}
U_g^{\mathrm{out}}\mathcal R_0(U_g^{\mathrm{in}})^{-1}
\end{equation}
intertwines the two actions. If the output action preserves the circle measure, mean-zero projection also intertwines it.

\label{thm:cusp}
Let $r\in\mathbb R$ and suppose $A_C\Psi=(1/4+r^2)\Psi$. For each nonzero Fourier index $n$, the solution that decays as $y\to\infty$ is a scalar multiple of
\begin{equation}\label{eq:cuspwave}
W_{n,r}(x,y)=\sqrt yK_{ir}(2\pi|n|y)e^{2\pi inx}.
\end{equation}
The zero mode is a linear combination of $y^{1/2+ir}$ and $y^{1/2-ir}$ for $r\ne0$, and of $y^{1/2}$ and $y^{1/2}\log y$ for $r=0$.

\label{prop:collar}
Fix $r\in\mathbb R$ and choose $Y$ sufficiently large that $K_{ir}(2\pi nY)\ne0$ for all $n\ge1$. For a smooth mean-zero trace $b(x)=\sum_{n\ne0}b(n)e^{2\pi inx}$, the decaying collar solution is
\begin{equation}\label{eq:collarsolution}
\Psi_b(x,y)=\sum_{n\ne0}b(n)
\frac{\sqrt yK_{ir}(2\pi|n|y)}{\sqrt YK_{ir}(2\pi|n|Y)}e^{2\pi inx},
\qquad y\ge Y.
\end{equation}
It has trace $b$ at $Y$. On each region $y\ge Y+\varepsilon$, the series and all derivatives converge normally.

In the Fourier--Bessel expansion, the wave coefficients are
\begin{equation}
A(n)=\frac{b(n)}{\sqrt YK_{ir}(2\pi|n|Y)}.
\end{equation}
A smooth collar trace can therefore lead to exponentially growing $A(n)$. A full Mellin integral down to $y=0$ requires an additional global coefficient condition. The local formula~\eqref{eq:collarsolution} is valid on its stated collar without that condition.

\label{thm:bulk}
For $f\in L^1(S^2)$ and $\beta\in\mathbb C$, define
\begin{equation}\label{eq:bulkPoisson}
(\mathcal H_\beta f)(X)=\int_{S^2}
\left(\frac{1-|X|^2}{|X-\xi|^2}\right)^\beta f(\xi)\,d\omega(\xi).
\end{equation}
Then $\mathcal H_\beta f$ is smooth in the ball and
\begin{equation}
A_{\mathbb H^3}\mathcal H_\beta f=\beta(2-\beta)\mathcal H_\beta f.
\end{equation}
The transform is equivariant for the orthogonal action preserving the ball, including $\Pi_3$.

\label{lem:bulktrace}
Let $N\cong\mathbb H^2$ be a totally geodesic plane in $\mathbb H^3$, let $r$ be signed normal distance, and let $U$ be a smooth bulk eigenfunction with $A_{\mathbb H^3}U=\lambda U$. Its trace $u=U|_N$ satisfies
\begin{equation}
A_Nu=\lambda u+\partial_r^2U|_{r=0}.
\end{equation}

\label{lem:BesselMellin}
For $\nu\in\mathbb C$, $c>0$, and $\Re s>|\Re\nu|$,
\begin{equation}\label{eq:BesselMellin}
\int_0^\infty K_\nu(cy)y^{s-1}\,d y
=2^{s-2}c^{-s}\Gamma\!\left(\frac{s+\nu}{2}\right)
\Gamma\!\left(\frac{s-\nu}{2}\right).
\end{equation}

\label{thm:maassFE}
Let $u$ be a weight-zero Maass cusp form for $\operatorname{PSL}(2,\mathbb Z)$ with eigenvalue $1/4+r^2$, $r\in\mathbb R$, and parity $\delta\in\{0,1\}$:
\begin{equation}
u(-x+iy)=(-1)^\delta u(x+iy),\qquad
u(z)=\sqrt y\sum_{n\ne0}A(n)K_{ir}(2\pi|n|y)e^{2\pi inx}.
\end{equation}
Assume the usual polynomial growth of its Fourier coefficients. Then
\begin{equation}
\Lambda_u(s)=\pi^{-(s+\delta)}
\Gamma\!\left(\frac{s+\delta+ir}{2}\right)
\Gamma\!\left(\frac{s+\delta-ir}{2}\right)
\sum_{n\ge1}A(n)n^{-s}
\end{equation}
extends to an entire function and satisfies
\begin{equation}\label{eq:MaassFE}
\Lambda_u(s)=(-1)^\delta\Lambda_u(1-s).
\end{equation}

\label{prop:latticereciprocity}
For every $t>0$,
\begin{equation}\label{eq:latticereciprocity}
\theta_L(t)=v^{-1}t^{-k/2}\theta_{L^*}(1/t),
\qquad
\Theta_L(t)=t^{-k/2}\Theta_{L^*}(1/t).
\end{equation}

\label{def:thetapair}
A reciprocal theta pair of weight $k>0$ consists of smooth kernels $\theta_\pm:(0,\infty)\to\mathbb C$ and constants $a_\pm$ such that
\begin{equation}\label{eq:pairedreciprocity}
\theta_+(t)=t^{-k/2}\theta_-(1/t),
\end{equation}
and $\theta_\pm(t)-a_\pm$ decay exponentially as $t\to\infty$. Families of such pairs are required to have locally uniform decay bounds in their other parameters whenever parameterwise analytic continuation is used.

\label{thm:pairedMellin}
For $\Re s>k$, define
\begin{equation}
\Lambda_\pm(s)=\frac12\int_0^\infty(\theta_\pm(t)-a_\pm)t^{s/2}\frac{\,d t}{t}.
\end{equation}
These functions extend meromorphically to $\mathbb C$ by
\begin{align}\label{eq:pairedMellin}
\Lambda_\pm(s)={}&-\frac{a_\pm}{s}+\frac{a_\mp}{s-k}\\
&+\frac12\int_1^\infty\left[(\theta_\pm(t)-a_\pm)t^{s/2}
+(\theta_\mp(t)-a_\mp)t^{(k-s)/2}\right]\frac{\,d t}{t}.\nonumber
\end{align}
They satisfy $\Lambda_+(s)=\Lambda_-(k-s)$. Their only possible poles are at $0,k$, with residues $-a_\pm,a_\mp$, respectively. The regularized functions
$\Xi_\pm(s)=s(s-k)\Lambda_\pm(s)$ are entire and obey the same paired reflection.

\label{cor:normalizedw}
At weight $k$, put $s=kw$ and $\widetilde\Lambda_\pm(w)=\Lambda_\pm(kw)$. Then
\begin{equation}
\widetilde\Lambda_+(w)=\widetilde\Lambda_-(1-w).
\end{equation}
The residues at $w=0,1$ are $-a_\pm/k,a_\mp/k$.

\label{lem:marginal}
On Schwartz spaces,
\begin{equation}\label{eq:Fourierexchange}
\pi\mathcal F_{k+1}=\mathcal F_k\rho,
\qquad
\rho\mathcal F_{k+1}=\mathcal F_k\pi.
\end{equation}

\label{prop:Gaussianlift}
Let $g(u)=e^{-\pi u^2}$ and $Ef=f\otimes g$. Then
\begin{equation}
\rho E=\pi E=\mathrm{id},\qquad
\mathcal F_{k+1}E=E\mathcal F_k.
\end{equation}
On the image of $E$, integration is a Fourier-compatible inverse to the lift.

\label{thm:ranktwo}
For $\Re s_1,\Re s_2>1$,
\begin{equation}\label{eq:ranktwointegral}
\mathcal L_2(s_1,s_2):=\int_0^\infty\!\int_0^\infty
h(t_1)h(t_2)t_1^{s_1/2}t_2^{s_2/2}
\frac{\,d t_1}{t_1}\frac{\,d t_2}{t_2}
=\Lambda_{\zeta}(s_1)\Lambda_{\zeta}(s_2).
\end{equation}
After meromorphic continuation,
\begin{equation}\label{eq:ranktworesidue}
\operatorname{Res}_{s_2=1}\mathcal L_2(s_1,s_2)=\Lambda_{\zeta}(s_1),\qquad
-\operatorname{Res}_{s_2=0}\mathcal L_2(s_1,s_2)=\Lambda_{\zeta}(s_1).
\end{equation}
With $R_2F(s_1,s_2)=F(1-s_1,1-s_2)$, $R_1f(s)=f(1-s)$,
$U_+=\operatorname{Res}_{s_2=1}$, and $U_-=-\operatorname{Res}_{s_2=0}$, the dual transition law is
\begin{equation}\label{eq:residueintertwine}
U_-R_2=R_1U_+.
\end{equation}

\label{def:doubledbase}
Define
\begin{equation}
\widehat{\mathfrak S}_\pm=\varprojlim_{n\ge3}\mathfrak S_n^\pm,
\qquad
\mathbb L=\widehat{\mathfrak S}_-\sqcup_{\mathfrak S_3}\widehat{\mathfrak S}_+,
\end{equation}
using the embeddings $j_\pm=(j_n^\pm)_n$ for the pushout. If the seed symbols are used as objects in a category of enriched structures, these formulas refer to limits and pushouts in the stated realization category.

\label{def:Mellintransition}
A transition $U_n^\pm:\mathscr M(W_{n+1})\to\mathscr M(W_n)$ is Mellin-compatible with $T_n^\pm$ if
\begin{equation}\label{eq:Mellincompatibility}
\mathcal M_n^\pm T_n^\pm=U_n^\pm\mathcal M_{n+1}^\pm
\end{equation}
on the stated domain. Parameter changes, constant-term subtractions, and residue prescriptions belong to the maps in this identity.

\label{thm:assembly}
Assume the geometric hypotheses defining $D$ in Theorem~\ref{thm:baseduality}, Mellin compatibility~\eqref{eq:Mellincompatibility}, and dual compatibility~\eqref{eq:dualcompatibility}. Then:
\begin{enumerate}
\item A compatible theta state $\theta=(\theta_n)$ over $x$ gives a compatible completed state
\begin{equation}\label{eq:universalstate}
\mathcal Z(x,\theta)=\bigl(\mathcal M_n^\pm\theta_n\bigr)_{n\ge3}.
\end{equation}
\item Duality sends $\theta$ to the compatible state $J\theta=(J_n\theta_n)$ over $Dx$, and
\begin{equation}\label{eq:universalFE}
\mathcal Z(Dx,J\theta)=R\mathcal Z(x,\theta),
\end{equation}
where $R$ acts by $R_n$ on each level.
\item If compatible identifications of the state families and their completed states are supplied over the common three-seed, the two constructions descend through those identifications to the doubled base. A self-dual rank-one state over the common seed obeys $\Lambda(s)=\Lambda(1-s)$.
\end{enumerate}

For the first assertion,
\begin{equation}
U_n^\pm\mathcal M_{n+1}^\pm\theta_{n+1}
=\mathcal M_n^\pm T_n^\pm\theta_{n+1}
=\mathcal M_n^\pm\theta_n.
\end{equation}
For the second, the first identity of~\eqref{eq:dualcompatibility} gives
$T_n^-J_{n+1}\theta_{n+1}=J_n\theta_n$.
The middle identity gives its Mellin state as $R_n\mathcal M_n^+\theta_n$, and the last identity makes these reflected states compatible with the negative transitions. The inverse maps prove involutivity.

For the third, the supplied identifications make the maps equal on representatives that are to be identified over the seed. They descend by the quotient universal property, as in Lemma~\ref{lem:quotientdescent}. At a fixed geometric point and self-dual fiber state,~\eqref{eq:universalFE} becomes its scalar functional equation. Rank one gives the normalization $s\mapsto1-s$.

\label{prop:divisor}
Let $F$ be a nonzero meromorphic section and let an involution $\iota$ satisfy $\iota^*F=\varepsilon F$, where $\varepsilon$ is nowhere vanishing and holomorphic. Then
\begin{equation}
\iota^*\operatorname{div}(F)=\operatorname{div}(F).
\end{equation}
In rank one, zeros and poles occur in configurations invariant under $s\mapsto1-s$.

\label{prop:detcriterion}
Let $K$ be compact, self-adjoint, and Hilbert--Schmidt, with nonzero real eigenvalues $\kappa_j$ counted with multiplicity. Then
\begin{equation}
\det{}_2(I-zK)=\prod_j(1-z\kappa_j)e^{z\kappa_j}
\end{equation}
is entire and all its zeros are real. If a zero-free entire function $E$ satisfies
\begin{equation}\label{eq:detcriterion}
E(z)\,\xi(\tfrac12+iz)=\det{}_2(I-zK),
\end{equation}
then every zero of $\xi(s)$ lies on $\Re s=1/2$.

\label{prop:holonomy}
The isomorphism classes of unitary rank-one local systems on $\Gamma_3$ form
\begin{equation}
\operatorname{Hom}(H_1(\Gamma_3;\mathbb Z),U(1))\cong U(1)^7.
\end{equation}
An equivariant local system additionally has lifts of the $\Pi_3$ action to its fibers, preserving parallel transport and satisfying the group law.

\label{prop:octonionlift}
Suppose a group acts on the seven labels by $\pi_g$, and choose signs $\sigma_{g,i}\in\{\pm1\}$. The maps
$U_g(1)=1$, $U_g(e_i)=\sigma_{g,i}e_{\pi_g(i)}$
define an action by octonion algebra automorphisms precisely when they satisfy the group law and, for every oriented product $e_ie_j=\varepsilon_{ij}e_k$,
\begin{equation}
\sigma_{g,i}\sigma_{g,j}e_{\pi_g(i)}e_{\pi_g(j)}
=\varepsilon_{ij}\sigma_{g,k}e_{\pi_g(k)}.
\end{equation}
